import org.junit.Test;
import static org.junit.Assert.*;
import java.util.ArrayList;
import java.util.List;
import java.util.Stack;

public class OnlineStockSpanTest {

  @Test
  public void nextTest() {
    OnlineStockSpan stockSpan = new OnlineStockSpan();
    assertEquals(1, stockSpan.next(10));
    assertEquals(2, stockSpan.next(20));
    assertEquals(1, stockSpan.next(15));
    assertEquals(4, stockSpan.next(5));
  }

  @Test
  public void calculateSpansTest() {
    OnlineStockSpan stockSpan = new OnlineStockSpan();
    int[] prices = new int[] { 10, 20, 15, 5 };
    int[] expectedSpans = new int[] { 1, 2, 1, 4 };
    assertArrayEquals(expectedSpans, stockSpan.calculateSpans(prices));
  }

}
```

This code tests the `next` and `calculateSpans` methods of the `OnlineStockSpan` class. The `nextTest` method tests the `next` method by adding prices to the stock and checking the span returned by the method. The `calculateSpansTest` method tests the `calculateSpans` method by providing a sample array of prices and checking the returned spans array.
